{"i":1,"chunk_id":"1e9677","wall_time_seconds":0.3923118,"exit_code":0,"original_token_count":4806,"output":"# Windows-only fresh quiescent proof; Execute alone reboots into idle Fastboot.
[CmdletBinding()]
param(
  [Alias('Mode')][ValidateSet('Check','Inventory','Audit','Execute')][string]$ResetMode='Check',
  [string]$Output='', [string]$DisplayStatus='', [string]$DisplaySha256='',
