# remain unchanged; a recovered last CC13 does not erase earlier CC4 failures.
function Get-ReviewedCc4History([string]$Body) {
  $pattern='\AK7 CAPTURE attempted=1 active=0 stop_requested=1 result=0\n'+
    'K7 CAPTURE_DIAG stage=9 banks=(?<banks>[1-9][0-9]*) packets=(?<good>[1-9][0-9]*) bad=(?<bad>[1-9][0-9]*) jpegs=(?<jpegs>[1-9][0-9]*) eof=(?<eof>[1-9][0-9]*) invalid=(?<invalid>[0-9]+) markers=(?<markers>[0-9]+) uvc_errors=(?<uvc>[0-9]+) bank_age_ms=(?<bank>[0-9]+) jpeg_age_ms=(?<jpeg>[0-9]+)\n'+
    'UVC FLOW last_cc=13 good=\k<good> bad=\k<bad>\n'+
    'UVC FLOW_CC code=4 count=\k<bad>\nUVC FLOW_CC code=13 count=\k<good>\z'
  $m=[regex]::Match($Body,$pattern)
  if(-not $m.Success){throw 'Not the exact reviewed stopped CC4-history/last-CC13 form'}
  foreach($key in @('banks','good','bad','jpegs','eof','invalid','markers','uvc')){
    [uint32]$checkedCounter=$m.Groups[$key].Value
  }
  if([uint64]$m.Groups['banks'].Value*256 -ne [uint64]$m.Groups['good'].Value+[uint64]$m.Groups['bad'].Value){throw 'Stopped CC4 history bank/slot accounting mismatch'}
  if([uint32]$m.Groups['jpegs'].Value -gt [uint32]$m.Groups['eof'].Value){throw 'JPEG/EOF accounting mismatch'}
  [uint64]$bank=$m.Groups['bank'].Value;[uint64]$jpeg=$m.Groups['jpeg'].Value
  $normalized=$Body -creplace 'bank_age_ms=[0-9]+','bank_age_ms=<age>'
  $normalized=$normalized -creplace 'jpeg_age_ms=[0-9]+','jpeg_age_ms=<age>'
  return @{normalized_body=$normalized;bank_age_ms=$bank;jpeg_age_ms=$jpeg;history_cc4=$true;zero_error_health=$false}
}

function Get-ReviewedCaptureRecord([string]$Body) {
  if($Body.StartsWith('K7 CAPTURE attempted=1 active=0 stop_requested=1 result=-5'+"`n")){return Get-ReviewedTransportFailure $Body}
  if($Body.StartsWith('K7 CAPTURE attempted=1 active=0 stop_requested=1 result=0'+"`n") -and $Body -cmatch '(?m)^K7 CAPTURE_DIAG stage=9 banks=[1-9][0-9]* packets=[1-9][0-9]* bad=[1-9][0-9]* '){return Get-ReviewedCc4History $Body}
  $healthy=$Body -creplace '(?<= invalid=)[0-9]+(?= markers=)','0'
  $healthy=$healthy -creplace '(?<= uvc_errors=)[0-9]+(?= bank_age_ms=)','0'
  Test-StoppedCapture $healthy
  $ages=[regex]::Match($Body,' bank_age_ms=(?<bank>[0-9]+) jpeg_age_ms=(?<jpeg>[0-9]+)\n')
  if(-not $ages.Success){throw 'Reviewed capture requires complete stage-9 diagnostics'}
  # These source fields are uint32 counters; only the two elapsed ages are u64.
  foreach($m in [regex]::Matches($Body,'(?:banks|packets|jpegs|eof|invalid|markers|uvc_errors)=(?<value>[0-9]+)')){
    [uint32]$checkedCounter=$m.Groups['value'].Value
  }
  [uint64]$bank=$ages.Groups['bank'].Value;[uint64]$jpeg=$ages.Groups['jpeg'].Value
  $normalized=$Body -creplace 'bank_age_ms=[0-9]+','bank_age_ms=<age>'
  $normalized=$normalized -creplace 'jpeg_age_ms=[0-9]+','jpeg_age_ms=<age>'
  return @{normalized_body=$normalized;bank_age_ms=$bank;jpeg_age_ms=$jpeg}
}
function Set-QuiescentCaptureProof([string]$Path,[string]$Sha256,[string]$Policy) {
  $script:quiescentCaptureProof=$null;$script:quiescentCaptureLast=$null
  if(-not $Path -and -not $Sha256){return}
  if(-not $Path -or $Sha256 -notmatch '\A[0-9a-fA-F]{64}\z' -or $Policy -cne 'StoppedDisplay'){
    throw 'CaptureStatus and exact CaptureSha256 require StoppedDisplay policy'
  }
"}

