 $standalone='[ \t]*'+$Count+' blocks read: OK[ \t]*'
 $complete='[ \t]*MMC read: dev # 0, block # '+$Lba+', count '+$Count+' \.\.\.[ \t]*'+$Count+' blocks read: OK[ \t]*'
 if($reply -notmatch ('(?m)^(?:'+$standalone+'|'+$complete+')\r?$')){throw 'MMC read incomplete'}
}
function Read-BackupChunk([uint64]$Address,[int]$Length) {
 $cmd='md.l '+$Address.ToString('x')+' '+([int]($Length/4)).ToString('x')
 for($attempt=0;$attempt -le $ReadRetries;$attempt++) {
  $event=@{address=$Address.ToString('x');bytes=$Length;attempt=($attempt+1);state='intended'}
  $nativeReport.read_attempts+=,$event;Save-Native
  # A transport timeout is outside decoder recovery: no prompt, no repeat.
  try {$reply=Command-Backup $cmd} catch {$event.state='transport_failed';$event.error=$_.Exception.Message;Save-Native;throw}
  try {
   $bytes=[VelaVision.NativeMdDecoder]::Decode($reply,$Address,$Length,$cmd)
   $event.state='decoded';Save-Native;return ,$bytes
  } catch [FormatException] {
   $event.state='decode_failed';$event.error=$_.Exception.Message
   $event.retry=($nativeReport.prompt_known -and $attempt -lt $ReadRetries);Save-Native
   if(-not $event.retry){throw}
  }
 }
 throw 'Read attempt limit reached'
}
