"""ROOT-only exact-program execution and checked build-artifact collection."""
from pathlib import Path, PurePosixPath
import argparse, hashlib, importlib.util, json, subprocess, tarfile

def sha(raw):
    return hashlib.sha256(raw).hexdigest()

p = argparse.ArgumentParser()
p.add_argument('--program', type=Path, required=True)
p.add_argument('--sha256', required=True)
p.add_argument('--remote-out', required=True)
p.add_argument('--out', type=Path, required=True)
a = p.parse_args()
code = a.program.read_bytes()
assert sha(code) == a.sha256
assert a.remote_out.startswith('/dev/shm/') and '..' not in PurePosixPath(a.remote_out).parts
root = Path(__file__).resolve().parents[3]
assert a.out.resolve().is_relative_to(Path(__file__).resolve().parent)
helper = root/'tools/cloud_radio_stage_audit.py'
assert sha(helper.read_bytes()) == '37e1dfcdd0f8051f98990a7178d5d29331ab0021d0ace2da3f24857ab65d26d6'
spec = importlib.util.spec_from_file_location('root_only_ssh', helper)
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)
a.out.mkdir(exist_ok=False)
(a.out/'executed_remote.py').write_bytes(code)
q = subprocess.run(module.SSH+['python3 -'], input=code, capture_output=True, timeout=900)
(a.out/'transport.stdout').write_bytes(q.stdout)
(a.out/'transport.stderr').write_bytes(q.stderr)
assert q.returncode == 0, q.stderr.decode(errors='replace')
reply = json.loads(q.stdout)
assert reply['bundle'] == a.remote_out+'.tgz' and 0 < reply['bytes'] < 536870912
fetch = ('from pathlib import Path\nimport hashlib,sys\n'
         'b=Path('+repr(reply['bundle'])+').read_bytes()\n'
         'assert len(b)=='+str(reply['bytes'])+' and hashlib.sha256(b).hexdigest()=='+repr(reply['sha256'])+'\n'
         'sys.stdout.buffer.write(b)\n')
q = subprocess.run(module.SSH+['python3 -'], input=fetch.encode(), capture_output=True, timeout=180)
(a.out/'fetch.stderr').write_bytes(q.stderr)
assert q.returncode == 0 and len(q.stdout) == reply['bytes'] and sha(q.stdout) == reply['sha256']
bundle = a.out/'artifacts.tgz'
bundle.write_bytes(q.stdout)
dest = a.out/'artifacts'
dest.mkdir()
with tarfile.open(bundle, 'r:gz') as archive:
    members = archive.getmembers()
    names = {m.name:m for m in members}
    assert len(names) == len(members) and all(m.isfile() for m in members)
    assert len({n.casefold() for n in names}) == len(names)
    assert sum(m.size for m in members) < 1073741824
    for n in names:
        part = PurePosixPath(n)
        assert not part.is_absolute() and '..' not in part.parts and '\\' not in n and ':' not in n
    raw = archive.extractfile(names['export-manifest.json']).read()
    assert sha(raw) == reply['manifest_sha256']
    inventory = json.loads(raw)
    assert set(names) == set(inventory['files'])|{'export-manifest.json'}
    for n,m in names.items():
        raw = archive.extractfile(m).read()
        if n != 'export-manifest.json':
            assert len(raw) == inventory['files'][n]['bytes'] and sha(raw) == inventory['files'][n]['sha256']
        path = dest/n
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(raw)
assert sha((dest/'result.json').read_bytes()) == reply['result_sha256']
print(json.dumps(reply))
"}

